  FT["PH-H10479"] = {"id":"PH-H10479","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2024/ra_12091_2024.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Separating the Bokong National High School - Tabak Annex in Barangay Upper Pulacan, Municipality of Labangan, Province of Zamboanga del Sur from the Bokong National High School, Converting it into an Independent National High School to be Known as The Tabak National High School,and Appropriating Funds Therefor","orig":"An Act Separating the Bokong National High School - Tabak Annex in Barangay Upper Pulacan, Municipality of Labangan, Province of Zamboanga del Sur from the Bokong National High School, Converting it into an Independent National High School to be Known as The Tabak National High School,and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["administrative","education"],"docNumber":"Republic Act No. 12091","issuingBody":"Congress of the Philippines","promulgatedDate":"2024-12-13","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2024/ra_12091_2024.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H10479-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Bokong National High School - Tabak Annex in Barangay Upper Pulacan, Municipality of Labangan, Province of Zamboanga del Sur is hereby separated from the Bokong National High School and converted into an independent national high school to be known as the Tabak National High School."}},{"id":"PH-H10479-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"All personnel, assets, liabilities, and records of the Bokong National High School - Tabak Annex are hereby transferred to and absorbed by the Tabak National High School."}},{"id":"PH-H10479-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The Secretary of Education shall immediately include in the Department's program the operationalization of the Tabak National High School, the initial funding of which shall be charged against the current year's appropriation of the Bokong National High School - Tabak Annex. Thereafter, the amount necessary for the continued operation of the school shall be included in the annual General Appropriations Act."}},{"id":"PH-H10479-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Within ninety (90) days from the approval of this Act, the Secretary of Education shall formulate the rules and regulations implementing the provisions of this Act. Such implementing rules and regulations shall provide for the school's organization, administration, operations and management, in accordance with Republic Act No. 9155, or the \"Governance of Basic Education Act of 2001\", Republic Act No. 10533, or the \"Enhanced Basic Education Act of 2013\", and other basic education-related laws."}},{"id":"PH-H10479-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"This Act shall take effect after fifteen (15) days following its publication in the Official Gazette or in a national newspaper of general circulation."}}],"pack":"ph-p149"};
